import json,numpy as np
s=json.load(open('/app/output/spec.json'));D=np.load('/app/output/recheck_depth_egocentric_mirrored_camera.npy');K=np.array(s['cameras']['egocentric_mirrored_camera']['intrinsic_cv']);E=np.array(s['cameras']['egocentric_mirrored_camera']['mount']['extrinsic_cv']);Ei=np.linalg.inv(np.vstack([E,[0,0,0,1]]))
pts={'red_mouth':(486,97),'red_body':(511,112),'red_body2':(520,120),'cer_mouth':(592,222),'cer_body':(608,198),'white_mouth':(396,219),'white_body':(354,202),'white_up':(584,101)}
for n,(u,v) in pts.items():
 print(n)
 for dv,du in [(0,0),(0,4),(4,0),(-4,0),(0,-4)]:
  z=float(D[v+dv,u+du]); p=Ei@np.r_[np.linalg.inv(K)@np.array([u+du,v+dv,1])*z,1]; print((u+du,v+dv),'d',round(z,3),'world',np.round(p[:3],3))
PY

